constraints:
1 ≤ N ≤ 10^{5}

expected time complexity: O(Nlog(logN))
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def superPrimes(self, n):
		p = [0] * (n + 1)
		count = 0
		for i in range(2, int(n ** 0.5) + 1):
			if p[i] == 0:
				for j in range(i * i, n + 1, i):
					p[j] = 1
		for i in range(5, n + 1):
			if p[i] == 0 and p[i - 2] == 0:
				count += 1
		return count
